script.js
const state = {
  items: [],
  filtered: [],
  page: 1,
  pageSize: 9,
  search: '',
  category: 'all',
  sort: 'date_desc',
  onlyFav: false,
  favs: new Set(JSON.parse(localStorage.getItem('favs') || '[]'))
};

document.addEventListener('DOMContentLoaded', init);

async function init() {
  await loadContent();
  buildCategoryOptions();
  bindControls();
  applyAndRender();
}

async function loadContent() {
  try {
    const res = await fetch('content.json');
    const data = await res.json();
    state.items = data.items || [];
  } catch (e) {
    // 本地直接双击打开 index.html 时，浏览器会阻止 fetch；提供回退示例数据
    state.items = sampleData();
    console.warn('使用内置示例数据。建议用本地服务器运行。');
  }
}

function bindControls() {
  const qs = id => document.getElementById(id);
  qs('searchInput').addEventListener('input', e => { state.search = e.target.value.trim().toLowerCase(); state.page = 1; applyAndRender(); });
  qs('categorySelect').addEventListener('change', e => { state.category = e.target.value; state.page = 1; applyAndRender(); });
  qs('sortSelect').addEventListener('change', e => { state.sort = e.target.value; applyAndRender(); });
  qs('onlyFav').addEventListener('change', e => { state.onlyFav = e.target.checked; state.page = 1; applyAndRender(); });

  document.getElementById('modalClose').addEventListener('click', closeModal);
  document.getElementById('detailModal').addEventListener('click', (e) => { if (e.target.id === 'detailModal') closeModal(); });

  document.addEventListener('keydown', (e) => { if (e.key === 'Escape') closeModal(); });

  const form = document.getElementById('contactForm');
  form.addEventListener('submit', async (e) => {
    e.preventDefault();
    const status = document.getElementById('formStatus');
    status.textContent = '正在发送…';
    await new Promise(r => setTimeout(r, 600));
    status.textContent = '已收到，谢谢你的反馈！';
    form.reset();
  });
}

function buildCategoryOptions() {
  const set = new Set();
  state.items.forEach(it => (it.categories || []).forEach(c => set.add(c)));
  const select = document.getElementById('categorySelect');
  [...set].sort().forEach(c => {
    const opt = document.createElement('option');
    opt.value = c; opt.textContent = c;
    select.appendChild(opt);
  });
}

function applyAndRender() {
  const q = state.search;
  const cat = state.category;
  const onlyFav = state.onlyFav;

  let arr = state.items.filter(it => {
    const inSearch = !q || [it.title, it.excerpt, ...(it.tags || [])].join(' ').toLowerCase().includes(q);
    const inCategory = cat === 'all' || (it.categories || []).includes(cat);
    const inFav = !onlyFav || state.favs.has(it.id);
    return inSearch && inCategory && inFav;
  });

  arr.sort((a, b) => {
    const byTitle = a.title.localeCompare(b.title, 'zh');
    const byDate = new Date(a.date) - new Date(b.date);
    switch (state.sort) {
      case 'title_asc': return byTitle;
      case 'title_desc': return -byTitle;
      case 'date_asc': return byDate;
      case 'date_desc': return -byDate;
      default: return -byDate;
    }
  });

  state.filtered = arr;
  renderGrid();
  renderPager();
}

function renderGrid() {
  const grid = document.getElementById('contentGrid');
  grid.innerHTML = '';
  const start = (state.page - 1) * state.pageSize;
  const pageItems = state.filtered.slice(start, start + state.pageSize);

  pageItems.forEach(it => {
    const card = document.createElement('article');
    card.className = 'card';
    card.setAttribute('role', 'listitem');

    const media = document.createElement('div');
    media.className = 'card-media';
    if (it.thumbnail) media.style.backgroundImage = `url(${it.thumbnail})`;

    const body = document.createElement('div');
    body.className = 'card-body';

    const title = document.createElement('div');
    title.className = 'card-title';
    title.textContent = it.title;

    const meta = document.createElement('div');
    meta.className = 'card-meta';
    meta.innerHTML = `<span>${formatType(it.type)}</span><span>·</span><time datetime="${it.date}">${formatDate(it.date)}</time>`;

    const tags = document.createElement('div');
    tags.className = 'tags';
    (it.tags || []).forEach(t => {
      const tag = document.createElement('span');
      tag.className = 'tag';
      tag.textContent = t;
      tags.appendChild(tag);
    });

    const excerpt = document.createElement('p');
    excerpt.textContent = it.excerpt || '';

    const actions = document.createElement('div');
    actions.className = 'card-actions';
    const viewBtn = document.createElement('a');
    viewBtn.href = 'javascript:void(0)';
    viewBtn.className = 'button-link';
    viewBtn.textContent = '查看详情';
    viewBtn.addEventListener('click', () => openModal(it));

    const favBtn = document.createElement('button');
    favBtn.className = 'fav' + (state.favs.has(it.id) ? ' active' : '');
    favBtn.textContent = state.favs.has(it.id) ? '★ 已收藏' : '☆ 收藏';
    favBtn.addEventListener('click', () => toggleFav(it.id, favBtn));

    actions.appendChild(viewBtn);
    actions.appendChild(favBtn);

    body.appendChild(title);
    body.appendChild(meta);
    body.appendChild(tags);
    body.appendChild(excerpt);
    body.appendChild(actions);

    card.appendChild(media);
    card.appendChild(body);
    grid.appendChild(card);
  });

  if (pageItems.length === 0) {
    grid.innerHTML = '<p style="color:#9ca3af">没有匹配的内容。</p>';
  }
}

function renderPager() {
  const pager = document.getElementById('pager');
  pager.innerHTML = '';
  const pages = Math.ceil(state.filtered.length / state.pageSize) || 1;

  const makeBtn = (i, label = i) => {
    const btn = document.createElement('button');
    btn.textContent = label;
    if (i === state.page) btn.classList.add('active');
    btn.addEventListener('click', () => { state.page = i; renderGrid(); renderPager(); });
    return btn;
  };

  if (pages <= 1) return;
  pager.appendChild(makeBtn(Math.max(1, state.page - 1), '上一页'));
  for (let i = 1; i <= pages; i++) {
    if (i === 1 || i === pages || Math.abs(i - state.page) <= 2) {
      pager.appendChild(makeBtn(i));
    } else if (Math.abs(i - state.page) === 3) {
      const dots = document.createElement('span');
      dots.textContent = '…'; dots.style.color = '#9ca3af'; dots.style.padding = '8px';
      pager.appendChild(dots);
    }
  }
  pager.appendChild(makeBtn(Math.min(pages, state.page + 1), '下一页'));
}

function openModal(item) {
  const modal = document.getElementById('detailModal');
  document.getElementById('modalTitle').textContent = item.title;
  const body = document.getElementById('modalBody');
  body.innerHTML = '';

  if (item.type === 'article') {
    const content = document.createElement('div');
    content.innerHTML = item.body || '<p>正文待补充。</p>';
    body.appendChild(content);
  } else if (item.type === 'image') {
    const img = document.createElement('img');
    img.src = item.mediaUrl || item.thumbnail || '';
    img.alt = item.title;
    img.style.maxWidth = '100%';
    body.appendChild(img);
    if (item.body) {
      const cap = document.createElement('p');
      cap.style.color = '#9ca3af';
      cap.textContent = item.body;
      body.appendChild(cap);
    }
  } else if (item.type === 'video') {
    if (item.mediaUrl && item.mediaUrl.endsWith('.mp4')) {
      const video = document.createElement('video');
      video.src = item.mediaUrl;
      video.controls = true;
      video.style.width = '100%';
      body.appendChild(video);
    } else if (item.mediaUrl) {
      const link = document.createElement('a');
      link.href = item.mediaUrl; link.target = '_blank';
      link.textContent = '在新窗口播放视频';
      body.appendChild(link);
    } else {
      body.innerHTML = '<p>视频地址未配置。</p>';
    }
  } else {
    body.innerHTML = '<p>未知类型。</p>';
  }

  modal.classList.add('show');
  modal.setAttribute('aria-hidden', 'false');
}

function closeModal() {
  const modal = document.getElementById('detailModal');
  modal.classList.remove('show');
  modal.setAttribute('aria-hidden', 'true');
}

function toggleFav(id, btn) {
  if (state.favs.has(id)) {
    state.favs.delete(id);
  } else {
    state.favs.add(id);
  }
  localStorage.setItem('favs', JSON.stringify([...state.favs]));
  btn.classList.toggle('active');
  btn.textContent = state.favs.has(id) ? '★ 已收藏' : '☆ 收藏';
  if (state.onlyFav) applyAndRender();
}

function formatType(type) {
  const map = { article: '文章', image: '图片', video: '视频' };
  return map[type] || type;
}
function formatDate(str) {
  try {
    const d = new Date(str);
    return d.toLocaleDateString('zh-CN', { year: 'numeric', month: '2-digit', day: '2-digit' });
  } catch { return str; }
}

